  `updated_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `is_del` tinyint DEFAULT NULL COMMENT '删除标志：0正常，1删除',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565274` (`tid`) USING BTREE,
  KEY `idx_api_param_api_id` (`api_id`) USING BTREE,
  KEY `idx_api_param_del` (`is_del`) USING BTREE,
  KEY `idx_api_param_tenant_api_id_is_del` (`tenant_id`,`api_id`,`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='数据服务-数据服务接口参数';

