  `enabled` tinyint NOT NULL DEFAULT '0' COMMENT '启用标志',
  `created_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人标识',
