  `created_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565217` (`tid`) USING BTREE,
  UNIQUE KEY `uk_reconcile_diff_hash` (`tenant_id`,`run_id`,`diff_hash`) USING BTREE,
  KEY `fk_reconcile_diff_run` (`run_id`) USING BTREE,
  KEY `idx_reconcile_diff_bucket` (`bucket_id`) USING BTREE,
  KEY `idx_reconcile_diff_page` (`tenant_id`,`run_id`,`diff_type`,`created_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='数据对账-数据对账差异明细';

-- TABLE data_reconcile_field_rule_t
CREATE TABLE `data_reconcile_field_rule_t` (
