-- TABLE data_reconcile_policy_t
CREATE TABLE `data_reconcile_policy_t` (
  `tid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '2084109831682699264' COMMENT '租户标识',
  `policy_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '策略名称',
  `policy_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '策略编码',
  `access_task_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '访问任务标识',
  `compare_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'KEY' COMMENT '比较模式',
  `trigger_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发模式',
  `cron_expression` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '调度表达式表达式',
  `source_key_fields` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源键字段集合',
  `target_key_fields` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '目标键字段集合',
  `source_increment_field` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源增量字段',
  `target_increment_field` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '目标增量字段',
  `bucket_count` int NOT NULL DEFAULT '1' COMMENT '分桶数量',
  `fetch_size` int NOT NULL DEFAULT '2000' COMMENT '抓取大小',
  `diff_limit` bigint NOT NULL DEFAULT '100000' COMMENT '差异限制',
  `numeric_tolerance` decimal(30,10) NOT NULL DEFAULT '0.0000000000' COMMENT '数值容差',
  `null_equals_empty` tinyint NOT NULL DEFAULT '0' COMMENT '空值等于空值',
  `trim_strings` tinyint NOT NULL DEFAULT '1' COMMENT '去空格字符串集合',
  `ignore_case` tinyint NOT NULL DEFAULT '0' COMMENT '忽略案件',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态',
  `precheck_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '预检状态',
  `precheck_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '预检消息',
  `precheck_detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '预检详情',
  `prechecked_at` datetime(6) DEFAULT NULL COMMENT '已预检时间',
  `next_run_at` datetime(6) DEFAULT NULL COMMENT '下次运行时间',
  `last_run_at` datetime(6) DEFAULT NULL COMMENT '最近运行时间',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人标识',
  `created_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人标识',
  `updated_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  `is_del` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0正常，1删除',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565228` (`tid`) USING BTREE,
  UNIQUE KEY `uk_reconcile_policy_code` (`tenant_id`,`policy_code`,`is_del`) USING BTREE,
  KEY `idx_data_reconcile_policy_tenant_is_del` (`tenant_id`,`is_del`) USING BTREE,
  KEY `idx_reconcile_policy_schedule` (`status`,`trigger_mode`,`next_run_at`) USING BTREE,
  KEY `idx_reconcile_policy_task` (`tenant_id`,`access_task_id`,`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='数据对账-数据对账策略';

-- TABLE data_reconcile_run_t
CREATE TABLE `data_reconcile_run_t` (
  `tid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '2084109831682699264' COMMENT '租户标识',
