  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误编码',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误消息',
  `error_detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '错误详情',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '追踪标识',
  `started_at` datetime(6) DEFAULT NULL COMMENT '开始时间',
  `finished_at` datetime(6) DEFAULT NULL COMMENT '完成时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人标识',
  `created_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565233` (`tid`) USING BTREE,
  UNIQUE KEY `uk_reconcile_run_dedupe` (`tenant_id`,`dedupe_key`) USING BTREE,
  KEY `fk_reconcile_run_policy` (`policy_id`) USING BTREE,
  KEY `idx_reconcile_run_policy` (`tenant_id`,`policy_id`,`created_time`) USING BTREE,
  KEY `idx_reconcile_run_status` (`status`,`cancel_requested`,`created_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='数据对账-数据对账运行实例';

