-- TABLE rm_role_t
CREATE TABLE `rm_role_t` (
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '2084109831682699264' COMMENT '租户标识',
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `create_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人标识',
  `update_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人标识',
  `deleted` smallint DEFAULT '0' COMMENT '删除标志：0正常，1删除',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `status` smallint DEFAULT '0' COMMENT '状态',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '名称',
  `code_num` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '编码数量',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `app_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用标识',
  `sort_num` int DEFAULT '0' COMMENT '排序数量',
  `data_scope` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OWNER' COMMENT '角色全局数据范围：ALL、ORG、OWNER',
  PRIMARY KEY (`tenant_id`,`id`) USING BTREE,
  UNIQUE KEY `INDEX33565484` (`tenant_id`,`id`) USING BTREE,
  KEY `ix_rm_role_code` (`tenant_id`,`app_id`,`code_num`,`deleted`) USING BTREE,
  KEY `ix_sym_role_t_lf1` (`tenant_id`,`app_id`,`status`,`deleted`) USING BTREE
