  `fax_phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '传真电话',
  `fixed_phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '固定电话',
  `serial_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '序列编号',
  PRIMARY KEY (`tenant_id`,`id`) USING BTREE,
  UNIQUE KEY `INDEX33565497` (`tenant_id`,`id`) USING BTREE,
