) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程审批-审批操作审计';

-- TABLE wf_approval_delegation_t
CREATE TABLE `wf_approval_delegation_t` (
  `tid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '2084109831682699264' COMMENT '租户标识',
  `delegator_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '委托人用户标识',
  `delegate_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '受托人用户标识',
  `flow_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程编码',
  `start_time` datetime(6) NOT NULL COMMENT '开始时间',
  `end_time` datetime(6) NOT NULL COMMENT '结束时间',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '原因',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人标识',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人标识',
  `created_time` datetime(6) NOT NULL COMMENT '创建时间',
  `updated_time` datetime(6) NOT NULL COMMENT '更新时间',
  `is_del` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0正常，1删除',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565444` (`tid`) USING BTREE,
  KEY `idx_wf_delegate_active` (`tenant_id`,`delegate_user_id`,`status`,`is_del`,`start_time`,`end_time`) USING BTREE,
  KEY `idx_wf_delegator` (`tenant_id`,`delegator_user_id`,`status`,`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程审批-审批委托规则';

-- TABLE wf_approval_reminder_t
CREATE TABLE `wf_approval_reminder_t` (
  `tid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '2084109831682699264' COMMENT '租户标识',
  `instance_id` bigint NOT NULL COMMENT '实例标识',
  `task_id` bigint NOT NULL COMMENT '任务标识',
  `business_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务标识',
  `sender_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送人用户标识',
  `target_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '目标用户标识',
  `reminder_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'IN_APP' COMMENT '催办类型',
  `reminder_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '催办消息',
  `reminder_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '催办状态',
  `scheduled_time` datetime(6) NOT NULL COMMENT '计划时间',
  `sent_time` datetime(6) DEFAULT NULL COMMENT '已发送时间',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试数量',
  `last_error` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最近错误',
  `created_time` datetime(6) NOT NULL COMMENT '创建时间',
  `updated_time` datetime(6) NOT NULL COMMENT '更新时间',
  `is_del` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0正常，1删除',
  PRIMARY KEY (`tid`) USING BTREE,
  UNIQUE KEY `INDEX33565448` (`tid`) USING BTREE,
  KEY `idx_wf_reminder_due` (`tenant_id`,`reminder_status`,`scheduled_time`,`is_del`) USING BTREE,
  KEY `idx_wf_reminder_task` (`tenant_id`,`task_id`,`target_user_id`,`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程审批-审批催办记录';

-- TABLE wf_process_binding_t
CREATE TABLE `wf_process_binding_t` (
